// src/app.ts
function buildApp() {
  const docsPlugin = isProduction() ? new Elysia({ name: "keybox/docs-disabled" }) : openapi({
    documentation: {
      info: {
        title: "Keybox API",
        version: "1.0.0",
        description: "Keybox is currently designed specifically for securely storing AI provider API keys."
      },
      tags: [
        { name: "Auth", description: "Authentication" },
        { name: "Keybox", description: "Encrypted AI API key storage" },
        { name: "Users", description: "User management (CRUD)" }
      ],
      components: {
        securitySchemes: {
          bearerAuth: { type: "http", scheme: "bearer", bearerFormat: "JWT" }
        }
      }
    }
  });
  return new Elysia().use(helmetPlugin).use(corsPlugin).use(wrap(logger, { autoLogging: true })).use(normalRateLimit()).onError(({ code, error, set }) => {
    if (error instanceof AppError) {
      if (error.code === "RATE_LIMITED") {
        logger.warn({ event: "ratelimit.triggered" }, "Rate limit triggered");
      }
      set.status = error.status;
      return errorBody(error.code, error.message);
    }
    switch (code) {
      case "VALIDATION":
        set.status = 400;
        return errorBody("VALIDATION_ERROR", "Invalid request payload");
      case "PARSE":
        set.status = 400;
        return errorBody("VALIDATION_ERROR", "Malformed request body");
      case "NOT_FOUND":
        set.status = 404;
        return errorBody("NOT_FOUND", "Resource not found");
      default:
        logger.error({ err: error instanceof Error ? error.message : String(error) }, "Unhandled error");
        set.status = 500;
        return errorBody("INTERNAL_ERROR", "Internal server error");
    }
  }).use(docsPlugin).get("/health", () => successBody({ status: "ok" }), {
    detail: { summary: "Health check", tags: ["App"] }
  }).use(authRoutes).use(keyboxRoutes()).use(usersRoutes());
}

// src/index.ts
async function main() {
  const env3 = getEnv();
  await connectDatabase();
  const app = buildApp().listen(env3.PORT);
  logger.info({ port: env3.PORT, env: env3.NODE_ENV }, `\uD83D\uDD10 Keybox running at http://localhost:${env3.PORT} (docs: /openapi)`);
  const shutdown = async (signal) => {
    logger.info({ signal }, "Shutting down");
    await app.stop();
    process.exit(0);
  };
  process.on("SIGINT", () => void shutdown("SIGINT"));
  process.on("SIGTERM", () => void shutdown("SIGTERM"));
}
main().catch((err) => {
  logger.error({ err: err instanceof Error ? err.message : String(err) }, "Failed to start server");
  process.exit(1);
});
